#import <Cocoa/Cocoa.h>
#include "../default_maps.h"
#include <assert.h>
int main(void){@autoreleasepool{NSString *root=[@"/private/tmp" stringByAppendingPathComponent:NSUUID.UUID.UUIDString];NSURL *source=[NSURL fileURLWithPath:[root stringByAppendingPathComponent:@"bundled"]],*target=[NSURL fileURLWithPath:[root stringByAppendingPathComponent:@"Maps"]];NSFileManager *files=NSFileManager.defaultManager;[files createDirectoryAtURL:source withIntermediateDirectories:YES attributes:nil error:nil];[files createDirectoryAtURL:target withIntermediateDirectories:YES attributes:nil error:nil];NSURL *map=[target URLByAppendingPathComponent:@"1.png"];[@"user" writeToURL:map atomically:YES encoding:NSUTF8StringEncoding error:nil];for(NSString *name in @[@"1.png",@"2.jpg",@"README.md",@"m3maps terms of use.txt"])[@"default" writeToURL:[source URLByAppendingPathComponent:name] atomically:YES encoding:NSUTF8StringEncoding error:nil];NSError *error=nil;assert(installDefaultMapFiles(source,target,&error)&&!error);assert([[NSString stringWithContentsOfURL:map encoding:NSUTF8StringEncoding error:nil]isEqual:@"user"]);assert([files fileExistsAtPath:[target URLByAppendingPathComponent:@"2.jpg"].path]);assert(![files fileExistsAtPath:[target URLByAppendingPathComponent:@"README.md"].path]);assert([[NSString stringWithContentsOfURL:[target URLByAppendingPathComponent:@"m3maps terms of use.txt"] encoding:NSUTF8StringEncoding error:nil]isEqual:@"default"]);assert(installDefaultMapFiles(source,target,&error));assert(installDefaultMapFiles([source URLByAppendingPathComponent:@"absent"],target,&error));[files removeItemAtPath:root error:nil];puts("Defaults install missing images and terms, preserve existing files, ignore unrelated documentation, and safely repeat.");}return 0;}
